WITH `purchase orders` AS (SELECT CAST(1 AS SIGNED) AS `Purchase Order ID`,CAST(1 AS SIGNED) AS `Supplier ID`),`purchase order details` AS (SELECT CAST(1 AS SIGNED) AS `Purchase Order ID`,CAST(3 AS SIGNED) AS `Product ID`,CAST(1 AS DECIMAL(20,4)) AS `Quantity`,CAST(10 AS DECIMAL(20,4)) AS `Unit Cost` UNION ALL SELECT CAST(1 AS SIGNED) AS `Purchase Order ID`,CAST(3 AS SIGNED) AS `Product ID`,CAST(100 AS DECIMAL(20,4)) AS `Quantity`,CAST(NULL AS DECIMAL(20,4)) AS `Unit Cost`) SELECT purchase.`Supplier ID`,detail.`Product ID`,ROUND(SUM(detail.Quantity*detail.`Unit Cost`) OVER (PARTITION BY purchase.`Supplier ID`,detail.`Product ID`)/NULLIF(SUM(detail.Quantity) OVER (PARTITION BY purchase.`Supplier ID`,detail.`Product ID`),0),4) FROM `purchase orders` purchase JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` WHERE detail.Quantity IS NOT NULL AND detail.`Unit Cost` IS NOT NULL;
WITH `purchase orders` AS (SELECT CAST(1 AS SIGNED) AS `Purchase Order ID`,CAST(1 AS SIGNED) AS `Supplier ID`),`purchase order details` AS (SELECT CAST(1 AS SIGNED) AS `Purchase Order ID`,CAST(3 AS SIGNED) AS `Product ID`,CAST(1 AS DECIMAL(20,4)) AS `Quantity`,CAST(10 AS DECIMAL(20,4)) AS `Unit Cost` UNION ALL SELECT CAST(1 AS SIGNED) AS `Purchase Order ID`,CAST(3 AS SIGNED) AS `Product ID`,CAST(100 AS DECIMAL(20,4)) AS `Quantity`,CAST(NULL AS DECIMAL(20,4)) AS `Unit Cost`) SELECT purchase.`Supplier ID`,detail.`Product ID`,ROUND(SUM(detail.Quantity*detail.`Unit Cost`) OVER (PARTITION BY purchase.`Supplier ID`,detail.`Product ID`)/SUM(detail.Quantity) OVER (PARTITION BY purchase.`Supplier ID`,detail.`Product ID`),4) FROM `purchase orders` purchase JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` WHERE detail.Quantity IS NOT NULL AND detail.`Unit Cost` IS NOT NULL;
WITH `purchase orders` AS (SELECT CAST(1 AS SIGNED) AS `Purchase Order ID`,CAST(1 AS SIGNED) AS `Supplier ID`),`purchase order details` AS (SELECT CAST(1 AS SIGNED) AS `Purchase Order ID`,CAST(3 AS SIGNED) AS `Product ID`,CAST(1 AS DECIMAL(20,4)) AS `Quantity`,CAST(10 AS DECIMAL(20,4)) AS `Unit Cost` UNION ALL SELECT CAST(1 AS SIGNED) AS `Purchase Order ID`,CAST(3 AS SIGNED) AS `Product ID`,CAST(100 AS DECIMAL(20,4)) AS `Quantity`,CAST(NULL AS DECIMAL(20,4)) AS `Unit Cost`),weighted AS (SELECT purchase.`Supplier ID` supplier_id,detail.`Product ID` product_id,SUM(detail.Quantity*detail.`Unit Cost`) OVER (PARTITION BY purchase.`Supplier ID`,detail.`Product ID`) total_cost,SUM(detail.Quantity) OVER (PARTITION BY purchase.`Supplier ID`,detail.`Product ID`) total_quantity FROM `purchase orders` purchase JOIN `purchase order details` detail ON detail.`Purchase Order ID`=purchase.`Purchase Order ID` WHERE detail.Quantity IS NOT NULL AND detail.`Unit Cost` IS NOT NULL) SELECT DISTINCT supplier_id,product_id,ROUND(total_cost/NULLIF(total_quantity,0),4) FROM weighted;
